"""Generate P4 parameter order and hard validation bounds from the desktop schema."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render(fields, enum_name, count_name, guard, title):
    def symbol(field):
        return ''.join(word.title() for word in (field['group'] + '_' + field['name']).split('_'))
    def literal(value):
        return f'{float(value):.8g}' + ('.0f' if float(value).is_integer() else 'f')
    return '\n'.join([
        '// Generated by tools/generate_control_parameters.py; do not edit.',
        f'/** @file {enum_name}.h',
        f' * @brief {title}',
        ' */',
        '#pragma once', '#include <stddef.h>',
        f'namespace mmhand::control {{',
        f'enum {enum_name} : size_t {{',
        *[f'    {symbol(field)} = {i},' for i, field in enumerate(fields)],
        f'    {count_name} = {len(fields)}', '};',
        f'inline constexpr float k{enum_name}Minimum[] = {{',
        *[f'    {literal(field["minimum"])},' for field in fields], '};',
        f'inline constexpr float k{enum_name}Maximum[] = {{',
        *[f'    {literal(field["maximum"])},' for field in fields], '};',
        '} // namespace mmhand::control', '',
    ])


def render_main():
    schema = json.loads((ROOT / 'desktop/resources/config/control_parameters.schema.json').read_text(encoding='utf-8'))
    fields = schema['payloads']['main']['fields']
    return render(fields, 'Parameter', 'ParameterCount', 'ControlParameters',
                  '枚举顺序及硬校验边界。')


def render_ramp():
    schema = json.loads((ROOT / 'desktop/resources/config/control_parameters.schema.json').read_text(encoding='utf-8'))
    fields = schema['payloads']['ramp']['fields']
    return render(fields, 'RampParameter', 'RampParameterCount', 'RampParameters',
                  '渐进快速换向参数的枚举顺序及硬校验边界。')


if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    outputs = {
        ROOT / 'ESP32-P4/src/generated/ControlParameters.generated.h': render_main(),
        ROOT / 'ESP32-P4/src/generated/RampParameters.generated.h': render_ramp(),
    }
    for output, expected in outputs.items():
        if args.check:
            if not output.exists() or output.read_text(encoding='utf-8') != expected:
                raise SystemExit(f'Generated parameter header is out of date: {output}')
        else:
            output.write_text(expected, encoding='utf-8')
            print('WROTE:', output)
